/**
 * Msg defines the Msg service. Every message names the stream it acts on; the
 * two streams share one engine but never share state.
 */
export interface Msg {
  /**
   * UpdateParams defines a (governance) operation for updating the module
   * parameters. The authority defaults to the x/gov module account.
   */
  UpdateParams(request: MsgUpdateParams): Promise<MsgUpdateParamsResponse>;
  /** SetAllocations sets the sender's split within a stream. */
  SetAllocations(request: MsgSetAllocations): Promise<MsgSetAllocationsResponse>;
  /** ClaimAllocation pays an ADDRESS option's accrued ERTH to its recipient. */
  ClaimAllocation(request: MsgClaimAllocation): Promise<MsgClaimAllocationResponse>;
  /** AddIntegratedOption adds an INTEGRATED option to a stream (governance-gated). */
  AddIntegratedOption(request: MsgAddIntegratedOption): Promise<MsgAddIntegratedOptionResponse>;
  /** AddAddressOption adds an ADDRESS option to a stream (permissionless, fee-gated). */
  AddAddressOption(request: MsgAddAddressOption): Promise<MsgAddAddressOptionResponse>;
  /** ResetAllocations clears every vote in one stream (governance-gated). */
  ResetAllocations(request: MsgResetAllocations): Promise<MsgResetAllocationsResponse>;
}

